def sha(text): return hashlib.sha256(text.encode()).hexdigest()
def read(repo,path):
    text=canonical_source(repo,path).read_text(encoding='utf-8').replace('\r\n','\n')
    assert sha(text)==SOURCES[path],('original source changed',path)
    return text
def produce(repo,output):
    output=Path(str(output) if str(output).startswith('\\\\?\\') else '\\\\?\\'+str(output.absolute()))
    output.mkdir(parents=True,exist_ok=True)
    receipts=[]
    for row in RECIPES:
        full=read(repo,row['originalPath']); selected=full
        if 'selection' in row:
            a,b=row['selection'];assert full.count(a)==1 and full.count(b)==1
            selected=full[full.index(a):full.index(b)]
        assert sha(selected)==row['selectedOriginalSha256LF']
        body=selected
        for edit in row['edits']:
            i=edit['offset'];before=edit['before']
            assert body[i:i+len(before)]==before,edit['label']
            body=body[:i]+edit['after']+body[i+len(before):]
        assert sha(body)==row['adaptedSha256LF']
        inverse=body
        for edit in reversed(row['edits']):
            i=edit['offset'];after=edit['after'];assert inverse[i:i+len(after)]==after
            inverse=inverse[:i]+edit['before']+inverse[i+len(after):]
        assert inverse==selected
        target=output/row['output'];target.parent.mkdir(parents=True,exist_ok=True)
        header='// Generated from '+row['originalPath']+'; do not edit.\n// LF-normalized SHA-256: '+row['fullOriginalSha256LF']+'\n'
        target.write_text(header+row.get('prefix','')+body,encoding='utf-8',newline='\n')
        receipts.append(dict(source=row['originalPath'],output=row['output'],fullOriginalSha256LF=sha(full),selectedOriginalSha256LF=sha(selected),adaptedSha256LF=sha(body),fullSelectedInverse=True))
    (output/'listen-original-source-receipt.json').write_text(json.dumps(receipts,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo',type=Path,required=True);parser.add_argument('--output',type=Path)
    parser.add_argument('--inventory',action='store_true');args=parser.parse_args()
    if args.inventory:
        print(json.dumps([dict(path=p,mode='direct' if p.endswith('ListenVideoLayoutPolicy.kt') else 'policy-extract',sha256=h,features=['original-listen-video-pages'])for p,h in SOURCES.items()],ensure_ascii=False,indent=2))
    elif args.output: produce(args.repo,args.output)
    else:parser.error('Pass --output or --inventory')
